"""Route boundary tests; generated bytes are injected and prove no playback."""
import importlib.util
from importlib.machinery import SourceFileLoader
import io
import json
from pathlib import Path
from types import SimpleNamespace
import unittest
from unittest import mock

ROOT = Path(__file__).resolve().parent
SPEC = importlib.util.spec_from_loader(
    "creation_voice_route_pwa",
    SourceFileLoader("creation_voice_route_pwa", str(ROOT / "bin" / "preceptoros-pwa")))
PWA = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(PWA)


class Handler:
    def __init__(self, body=b"", headers=None, path="/api/creaciones/voz"):
        self.path = path
        self.headers = headers or {}
        self.rfile = io.BytesIO(body)
        self.wfile = io.BytesIO()
        self.server = SimpleNamespace(server_address=("127.0.0.1", 8740))
        self.code = None
        self.response_headers = {}

    def _json(self, code, body):
        self.code, self.body = code, body

    def send_response(self, code):
        self.code = code

    def send_header(self, name, value):
        self.response_headers[name] = value

    def end_headers(self):
        pass

    def _creacion_voz(self):
        return PWA.PWA._creacion_voz(self)

    def _creacion_publicar(self):
        return PWA.PWA._creacion_publicar(self)


def headers(body, **extra):
    value = {"Origin": "http://127.0.0.1:8740", "Host": "127.0.0.1:8740",
             "Content-Type": "application/json", "Content-Length": str(len(body))}
    value.update(extra)
    return value


def ok_result(profile="a" * 64):
    return {"estado": "ok", "catalog": {"profile_id": profile},
            "declaration": {"profile_id": profile}}


class CreationVoiceRoute(unittest.TestCase):
    def request(self, text="A statement.", route="/api/creaciones/voz", extra=None):
        raw = json.dumps({"text": text}, ensure_ascii=False).encode("utf-8")
        req = Handler(raw, headers(raw, **(extra or {})), route)
        return req

    def dispatch(self, req):
        return PWA.PWA._despachar_post(req)

    def test_exact_origin_and_matching_profiles_return_expected_json(self):
        req = self.request()
        with mock.patch.object(PWA._voz_creacion, "generar", return_value=ok_result()) as generate:
            self.dispatch(req)
        self.assertEqual(req.code, 200)
        self.assertEqual(req.response_headers["Content-Type"], "application/json; charset=utf-8")
        self.assertEqual(json.loads(req.wfile.getvalue()), ok_result())
        generate.assert_called_once_with("A statement.")

    def test_bad_origin_rejects_before_generation(self):
        req = self.request(extra={"Origin": "https://elsewhere.example"})
        with mock.patch.object(PWA._voz_creacion, "generar") as generate:
            self.dispatch(req)
        self.assertEqual(req.code, 403)
        generate.assert_not_called()

    def test_content_type_and_exact_request_shape_are_closed(self):
        raw = b'{"text":"hello","extra":true}'
        req = Handler(raw, headers(raw), "/api/creaciones/voz")
        with mock.patch.object(PWA._voz_creacion, "generar") as generate:
            self.dispatch(req)
        self.assertEqual(req.code, 400)
        generate.assert_not_called()
        req = self.request(extra={"Content-Type": "text/plain"})
        with mock.patch.object(PWA._voz_creacion, "generar") as generate:
            self.dispatch(req)
        self.assertEqual(req.code, 415)
        generate.assert_not_called()

    def test_body_limit_utf8_boundary_and_invalid_utf8_fail_closed(self):
        exact = json.dumps({"text": "á" * 512}, ensure_ascii=False).encode("utf-8")
        req = Handler(exact, headers(exact))
        with mock.patch.object(PWA._voz_creacion, "generar", return_value=ok_result()) as generate:
            self.dispatch(req)
        self.assertEqual(req.code, 200)
        generate.assert_called_once_with("á" * 512)

        too_long = json.dumps({"text": "á" * 513}, ensure_ascii=False).encode("utf-8")
        req = Handler(too_long, headers(too_long))
        with mock.patch.object(PWA._voz_creacion, "generar") as generate:
            self.dispatch(req)
        self.assertEqual(req.code, 400)
        generate.assert_not_called()

        invalid = b'{"text":"\xff"}'
        req = Handler(invalid, headers(invalid))
        with mock.patch.object(PWA._voz_creacion, "generar") as generate:
            self.dispatch(req)
        self.assertEqual(req.code, 400)
        generate.assert_not_called()

        oversized = b'{"text":"' + b'x' * 2040 + b'"}'
        req = Handler(oversized, headers(oversized))
        with mock.patch.object(PWA._voz_creacion, "generar") as generate:
            self.dispatch(req)
        self.assertEqual(req.code, 413)
        generate.assert_not_called()

    def test_request_body_cap_is_checked_before_reading(self):
        req = Handler()
        req.headers = {"Origin": "http://127.0.0.1:8740", "Host": "127.0.0.1:8740",
                       "Content-Type": "application/json", "Content-Length": "2049"}
        with mock.patch.object(PWA._voz_creacion, "generar") as generate:
            self.dispatch(req)
        self.assertEqual(req.code, 413)
        generate.assert_not_called()

    def test_generator_nodata_is_preserved_and_engine_cause_is_sanitized(self):
        cause = {"estado": "NO_DATA", "causa": "local voice engine or model unavailable"}
        req = self.request()
        with mock.patch.object(PWA._voz_creacion, "generar", return_value=cause):
            self.dispatch(req)
        self.assertEqual(req.code, 503)
        self.assertEqual(json.loads(req.wfile.getvalue()), cause)

    def test_profile_mismatch_invalid_result_and_oversized_result_rejected(self):
        req = self.request()
        result = ok_result("b" * 64)
        result["declaration"]["profile_id"] = "c" * 64
        with mock.patch.object(PWA._voz_creacion, "generar", return_value=result):
            self.dispatch(req)
        self.assertEqual(req.code, 503)
        self.assertIn("inconsistente", req.body["causa"])

        req = self.request()
        huge = {"estado": "NO_DATA", "causa": "x" * 2048}
        with mock.patch.object(PWA._voz_creacion, "generar", return_value=huge):
            with mock.patch.object(PWA._voz_creacion, "LIMITE", 100):
                self.dispatch(req)
        self.assertEqual(req.code, 413)

        req = self.request()
        with mock.patch.object(PWA._voz_creacion, "generar", return_value={"estado": "ok"}):
            self.dispatch(req)
        self.assertEqual(req.code, 503)

    def test_options_requires_exact_origin_post_and_content_type(self):
        req = Handler(path="/api/creaciones/voz", headers={
            "Origin": "http://127.0.0.1:8740", "Host": "127.0.0.1:8740",
            "Access-Control-Request-Method": "POST",
            "Access-Control-Request-Headers": "content-type"})
        PWA.PWA.do_OPTIONS(req)
        self.assertEqual(req.code, 204)
        self.assertEqual(req.response_headers["Access-Control-Allow-Origin"], "http://127.0.0.1:8740")

        denied = Handler(path="/api/creaciones/voz", headers={
            "Origin": "https://evil.example", "Host": "127.0.0.1:8740",
            "Access-Control-Request-Method": "POST"})
        PWA.PWA.do_OPTIONS(denied)
        self.assertEqual(denied.code, 403)

    def test_other_post_routes_keep_their_dispatch(self):
        req = Handler(path="/api/creaciones")
        with mock.patch.object(PWA.PWA, "_creacion_publicar", lambda self: setattr(self, "code", 201)):
            self.dispatch(req)
        self.assertEqual(req.code, 201)


if __name__ == "__main__":
    unittest.main()
